# Matcher patterns for Argumentative Rhetorical Structures & Concessive idioms
pattern_rhetorical_correlatives = [
    # Pattern A: d'une part ... d'autre part
    [
        {"LOWER": "d'"}, {"LOWER": "une"}, {"LOWER": "part"},
        {"OP": "*"},
        {"LOWER": "d'"}, {"LOWER": "autre"}, {"LOWER": "part"}
    ],
    # Pattern B: non seulement ... mais (aussi|encore)
    [
        {"LOWER": "non"}, {"LOWER": "seulement"},
        {"OP": "*"},
        {"LOWER": "mais"}, {"LOWER": {"IN": ["aussi", "encore"]}}
    ],
    # Pattern C: plus ... plus
    [
        {"LOWER": "plus"},
        {"OP": "+"},
        {"LOWER": ","},
        {"LOWER": "plus"}
    ],
    # Pattern D: certes ... mais
    [
        {"LOWER": "certes"},
        {"OP": "*"},
        {"LOWER": "mais"}
    ]
]

pattern_avoir_beau = [
    # Pattern 1: Conjugated avoir + beau + Verb(Inf) (e.g., "a beau dire", "avait beau faire")
    [
        {"LEMMA": "avoir"},
        {"OP": "*", "LEMMA": {"NOT_IN": ["mais", "et", "ou", "."]}},
        {"LOWER": "beau"},
        {"POS": "VERB", "MORPH": {"IS_SUBSET": ["VerbForm=Inf"]}}
    ],
    # Pattern 2: Infinitive inversion beau + avoir + Verb(Inf|Part) (e.g., "beau avoir révisé")
    [
        {"LOWER": "beau"},
        {"LEMMA": "avoir", "POS": {"IN": ["VERB", "AUX"]}},
        {"POS": "VERB"}
    ]
]
